1	/**
2	 * Outbound message operations (container side).
3	 *
4	 * Writes to outbound.db (container-owned).
5	 * The host polls this DB (read-only) for undelivered messages.
6	 */
7	import { getInboundDb, getOutboundDb } from './connection.js';
8	
9	export interface MessageOutRow {
10	  id: string;
11	  seq: number | null;
12	  in_reply_to: string | null;
13	  timestamp: string;
14	  deliver_after: string | null;
15	  recurrence: string | null;
16	  kind: string;
17	  platform_id: string | null;
18	  channel_type: string | null;
19	  thread_id: string | null;
20	  content: string;
21	}
22	
23	export interface WriteMessageOut {
24	  id: string;
25	  in_reply_to?: string | null;
26	  deliver_after?: string | null;
27	  recurrence?: string | null;
28	  kind: string;
29	  platform_id?: string | null;
30	  channel_type?: string | null;
31	  thread_id?: string | null;
32	  content: string;
33	}
34	
35	/** Re-sends within this window of an identical prior send are treated as duplicates. */
36	const DEDUP_WINDOW = '-60 seconds';
37	
38	/**
39	 * Write a new outbound message, auto-assigning an odd seq number.
40	 * Container uses odd seq (1, 3, 5...), host uses even (2, 4, 6...).
41	 *
42	 * The disjoint namespace is load-bearing, not just collision avoidance:
43	 * seq is the agent-facing message ID returned by send_message and accepted
44	 * by edit_message / add_reaction, and getMessageIdBySeq() below looks up
45	 * by seq across BOTH tables. If inbound and outbound could share a seq,
46	 * the agent's "edit message #5" could resolve to the wrong row.
47	 */
48	export function writeMessageOut(msg: WriteMessageOut): number {
49	  const outbound = getOutboundDb();
50	  const inbound = getInboundDb();
51	
52	  // Safety net against duplicate user-visible sends — e.g. the agent being
53	  // told (possibly wrongly) that its last response "was not delivered" and
54	  // resending the same content. Same channel/platform/in_reply_to/content
55	  // within the window is treated as a resend of the same message rather
56	  // than a new one, and the existing row's seq is returned so callers
57	  // (send_message, etc.) still get a valid reference.
58	  const dup = outbound
59	    .prepare(
60	      `SELECT seq FROM messages_out
61	       WHERE channel_type IS $channel_type
62	         AND platform_id IS $platform_id
63	         AND in_reply_to IS $in_reply_to
64	         AND content = $content
65	         AND timestamp >= datetime('now', $window)
66	       ORDER BY seq DESC LIMIT 1`,
67	    )
68	    .get({
69	      $channel_type: msg.channel_type ?? null,
70	      $platform_id: msg.platform_id ?? null,
71	      $in_reply_to: msg.in_reply_to ?? null,
72	      $content: msg.content,
73	      $window: DEDUP_WINDOW,
74	    }) as { seq: number } | undefined;
75	
76	  if (dup?.seq != null) {
77	    console.error(`[messages-out] Skipping duplicate outbound write — matches seq #${dup.seq} within ${DEDUP_WINDOW}`);
78	    return dup.seq;
79	  }
80	
81	  // Read max seq from both DBs to maintain global ordering.
82	  // Safe: each side only reads the other DB, never writes to it.
83	  const maxOut = (outbound.prepare('SELECT COALESCE(MAX(seq), 0) AS m FROM messages_out').get() as { m: number }).m;
84	  const maxIn = (inbound.prepare('SELECT COALESCE(MAX(seq), 0) AS m FROM messages_in').get() as { m: number }).m;
85	  const max = Math.max(maxOut, maxIn);
86	  const nextSeq = max % 2 === 0 ? max + 1 : max + 2; // next odd
87	
88	  // bun:sqlite requires named parameters to be passed with the prefix character
89	  // in the JS object keys (better-sqlite3 auto-stripped it, bun:sqlite does not).
90	  outbound
91	    .prepare(
92	      `INSERT INTO messages_out (id, seq, in_reply_to, timestamp, deliver_after, recurrence, kind, platform_id, channel_type, thread_id, content)
93	     VALUES ($id, $seq, $in_reply_to, datetime('now'), $deliver_after, $recurrence, $kind, $platform_id, $channel_type, $thread_id, $content)`,
94	    )
95	    .run({
96	      $id: msg.id,
