122	export function getMessageIdBySeq(seq: number): string | null {
123	  const inbound = getInboundDb();
124	
125	  // Inbound messages: ID is already the platform message ID
126	  const inRow = inbound.prepare('SELECT id FROM messages_in WHERE seq = ?').get(seq) as
127	    | { id: string }
128	    | undefined;
129	  if (inRow) return inRow.id;
130	
131	  // Outbound messages: look up platform message ID from delivered table
132	  const outRow = getOutboundDb().prepare('SELECT id FROM messages_out WHERE seq = ?').get(seq) as
133	    | { id: string }
134	    | undefined;
135	  if (!outRow) return null;
136	
137	  // Check if host has stored the platform message ID after delivery
138	  const deliveredRow = inbound
139	    .prepare('SELECT platform_message_id FROM delivered WHERE message_out_id = ?')
140	    .get(outRow.id) as { platform_message_id: string | null } | undefined;
141	  if (deliveredRow?.platform_message_id) return deliveredRow.platform_message_id;
