41	/**
42	 * Resolve a destination name to routing fields.
43	 *
44	 * If `to` is omitted, use the session's default reply routing (channel +
45	 * thread the conversation is in) — the agent replies in place.
46	 *
47	 * If `to` is specified, look up the named destination. If it resolves to
48	 * the same channel the session is bound to, the session's thread_id is
49	 * preserved so replies land in the correct thread. Otherwise thread_id
50	 * is null (a cross-destination send starts a new conversation).
51	 */
52	function resolveRouting(
53	  to: string | undefined,
54	): { channel_type: string; platform_id: string; thread_id: string | null; resolvedName: string } | { error: string } {
55	  if (!to) {
56	    // Default: reply to whatever thread/channel this session is bound to.
57	    const session = getSessionRouting();
58	    if (session.channel_type && session.platform_id) {
59	      return {
60	        channel_type: session.channel_type,
61	        platform_id: session.platform_id,
62	        thread_id: session.thread_id,
63	        resolvedName: '(current conversation)',
64	      };
65	    }
66	    // No session routing (e.g., agent-shared or internal-only agent) —
67	    // fall back to the legacy single-destination shortcut.
68	    const all = getAllDestinations();
69	    if (all.length === 0) return { error: 'No destinations configured.' };
70	    if (all.length > 1) {
71	      return {
72	        error: `You have multiple destinations — specify "to". Options: ${all.map((d) => d.name).join(', ')}`,
73	      };
74	    }
75	    to = all[0].name;
76	  }
77	  const dest = findByName(to);
78	  if (!dest) return { error: `Unknown destination "${to}". Known: ${destinationList()}` };
79	  if (dest.type === 'channel') {
80	    // If the destination is the same channel the session is bound to,
81	    // preserve the thread_id so replies land in the correct thread.
82	    const session = getSessionRouting();
83	    const threadId =
84	      session.channel_type === dest.channelType && session.platform_id === dest.platformId ? session.thread_id : null;
85	    return {
86	      channel_type: dest.channelType!,
87	      platform_id: dest.platformId!,
88	      thread_id: threadId,
89	      resolvedName: to,
90	    };
91	  }
92	  return { channel_type: 'agent', platform_id: dest.agentGroupId!, thread_id: null, resolvedName: to };
93	}
