5	/**
6	 * Command categories for messages starting with '/'.
7	 * - admin: sender must be in NANOCLAW_ADMIN_USER_IDS
8	 * - filtered: silently drop (mark completed without processing)
9	 * - passthrough: pass raw to the agent (no XML wrapping)
10	 * - none: not a command — format normally
11	 */
12	export type CommandCategory = 'admin' | 'filtered' | 'passthrough' | 'none';
13	
14	const ADMIN_COMMANDS = new Set(['/remote-control', '/clear', '/compact', '/context', '/cost', '/files', '/upload-trace']);
15	const FILTERED_COMMANDS = new Set(['/help', '/login', '/logout', '/doctor', '/config', '/start']);
16	
17	export interface CommandInfo {
18	  category: CommandCategory;
19	  command: string; // the command name (e.g., '/clear')
20	  text: string; // full original text
21	  senderId: string | null;
22	}
23	
24	/**
25	 * Categorize a message as a command or not.
26	 * Only applies to chat/chat-sdk messages.
27	 *
28	 * The extracted `senderId` is compared against `NANOCLAW_ADMIN_USER_IDS`
29	 * which stores ids in the namespaced form `<channel_type>:<raw>` (see
30	 * src/db/users.ts). chat-sdk-bridge serializes `author.userId` as a raw
31	 * platform id with no prefix, so we prefix it here. If the id already
32	 * contains a `:` we assume it's pre-namespaced (non-chat-sdk adapters
33	 * that populate `senderId` directly) and leave it alone.
34	 */
35	export function categorizeMessage(msg: MessageInRow): CommandInfo {
36	  const content = parseContent(msg.content);
37	  const text = (content.text || '').trim();
38	  const senderId = extractSenderId(msg, content);
39	
40	  if (!text.startsWith('/')) {
41	    return { category: 'none', command: '', text, senderId };
42	  }
43	
44	  // Extract the command name (e.g., '/clear' from '/clear some args')
45	  const command = text.split(/\s/)[0].toLowerCase();
46	
47	  if (ADMIN_COMMANDS.has(command)) {
48	    return { category: 'admin', command, text, senderId };
49	  }
50	
51	  if (FILTERED_COMMANDS.has(command)) {
52	    return { category: 'filtered', command, text, senderId };
53	  }
54	
55	  return { category: 'passthrough', command, text, senderId };
56	}
