58	/**
59	 * Narrow check for /clear — the only command the runner handles directly.
60	 * All other command gating (filtered, admin) is done by the host router
61	 * before messages reach the container.
62	 */
63	export function isClearCommand(msg: MessageInRow): boolean {
64	  const content = parseContent(msg.content);
65	  const text = (content.text || '').trim();
66	  return text.toLowerCase().startsWith('/clear');
67	}
