70	 * True for any chat that needs the outer loop's command path: /clear plus
71	 * admin/passthrough slash commands the SDK can only dispatch when they are
72	 * a query's first input. Used by the follow-up poller to bail out and let
73	 * the outer loop reopen the query.
74	 */
75	export function isRunnerCommand(msg: MessageInRow): boolean {
76	  if (msg.kind !== 'chat' && msg.kind !== 'chat-sdk') return false;
77	  const cat = categorizeMessage(msg).category;
78	  return cat === 'admin' || cat === 'passthrough';
79	}
