81	// eslint-disable-next-line @typescript-eslint/no-explicit-any
82	function extractSenderId(msg: MessageInRow, content: any): string | null {
83	  const raw: string | null = content?.senderId || content?.author?.userId || null;
84	  if (!raw) return null;
